begin
  select id into v_syllabus
  from public.science_syllabus_versions
  where syllabus_code = 'MOE-PRIMARY-SCIENCE-2023';

  if v_syllabus is null then
    raise exception 'MOE-PRIMARY-SCIENCE-2023 syllabus version is missing';
  end if;

  for r in select value from jsonb_array_elements($seed$[{"code":"P5-REPRO-STANDARD","track":"STANDARD","topic":"Cycles in Plants and Animals (Reproduction)","strand":"Cycles","source":"MOE 2023 syllabus, pp. 43–47","outcome_text":"Recognise that a cell is a basic unit of life.\nExplain that living things reproduce to ensure continuity of their kind and that many characteristics are passed from parents to offspring.\nDescribe sexual reproduction in flowering plants: pollination, fertilisation (seed production), seed dispersal and germination.\nRecognise fertilisation in human sexual reproduction: a sperm fuses with an egg; the fertilised egg develops in the womb; ovaries produce eggs and testes produce sperms.\nRecognise the similarity in fertilisation in flowering plants and humans.\nInvestigate plant reproduction by spores and seeds.","objectives":["Explain why living things reproduce.","Describe the sequence of sexual reproduction in flowering plants.","Explain fertilisation in flowering plants and humans at the required level.","Compare reproduction by spores and seeds."],"teaching_content":{"sections":[{"heading":"Why reproduction matters","content":"Living things reproduce to ensure that their kind continues. Offspring inherit many characteristics from their parents. A cell is the basic unit of life."},{"heading":"Flowering plant reproduction","content":"Pollination is the transfer of pollen grains from the anther to the stigma. After pollination, fertilisation occurs when the male reproductive cell fuses with the female reproductive cell. Seeds form; seeds may be dispersed away from the parent plant."},{"heading":"Germination and plant reproduction","content":"Germination is the growth of a seed into a young plant under suitable conditions. Some plants reproduce using spores; others reproduce using seeds."},{"heading":"Human fertilisation","content":"The ovaries produce eggs and the testes produce sperms. Fertilisation occurs when a sperm fuses with an egg. The fertilised egg develops in the womb. The syllabus does not require detailed foetal development."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Explain why living things reproduce.","Describe the sequence of sexual reproduction in flowering plants.","Explain fertilisation in flowering plants and humans at the required level.","Compare reproduction by spores and seeds."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"What is the basic unit of life?"},"options":[{"id":"0","text":"A cell"},{"id":"1","text":"An organ"},{"id":"2","text":"A tissue"},{"id":"3","text":"A system"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-standard-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"What is the main purpose of reproduction?"},"options":[{"id":"0","text":"To ensure continuity of a kind"},{"id":"1","text":"To help an organism breathe"},{"id":"2","text":"To make all offspring identical"},{"id":"3","text":"To produce food"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-standard-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"What is pollination?"},"options":[{"id":"0","text":"Transfer of pollen from anther to stigma"},{"id":"1","text":"Fusion of male and female cells"},{"id":"2","text":"Growth of a seed"},{"id":"3","text":"Dispersal of a fruit"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-standard-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"Which sequence is correct for flowering plant sexual reproduction?"},"options":[{"id":"0","text":"Pollination → fertilisation → seed dispersal → germination"},{"id":"1","text":"Germination → pollination → fertilisation → seed dispersal"},{"id":"2","text":"Fertilisation → germination → pollination → seed dispersal"},{"id":"3","text":"Seed dispersal → fertilisation → pollination → germination"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-standard-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"What happens during fertilisation in humans?"},"options":[{"id":"0","text":"A sperm fuses with an egg"},{"id":"1","text":"An egg fuses with a pollen grain"},{"id":"2","text":"A seed develops in the womb"},{"id":"3","text":"The ovaries produce sperms"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-standard-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which statement compares fertilisation in flowering plants and humans correctly?"},"options":[{"id":"0","text":"In both, a male reproductive cell fuses with a female reproductive cell"},{"id":"1","text":"Both use pollen grains"},{"id":"2","text":"Both occur in the womb"},{"id":"3","text":"Both produce spores"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-standard-Q6"}]},{"code":"P5-REPRO-FOUNDATION","track":"FOUNDATION","topic":"Cycles in Plants and Animals (Reproduction)","strand":"Cycles","source":"MOE 2023 syllabus, pp. 43–47","outcome_text":"State the processes in sexual reproduction of flowering plants: pollination, fertilisation (seed production), seed dispersal and germination.\nState the process of fertilisation in human sexual reproduction.\nObserve and compare how plants reproduce by spores and seeds.","objectives":["State the four processes in flowering plant reproduction.","Describe fertilisation in humans using the terms sperm and egg.","Observe and compare reproduction by spores and seeds."],"teaching_content":{"sections":[{"heading":"The four processes","content":"Flowering plants reproduce through pollination, fertilisation, seed dispersal and germination. Learn the processes in the correct order."},{"heading":"Fertilisation","content":"In flowering plants, fertilisation leads to the development of fruits and seeds. In humans, fertilisation occurs when a sperm fuses with an egg."},{"heading":"Spores and seeds","content":"Some plants reproduce by spores, while others reproduce by seeds. Observe their structures and compare how they differ."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["State the four processes in flowering plant reproduction.","Describe fertilisation in humans using the terms sperm and egg.","Observe and compare reproduction by spores and seeds."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which process comes first in the usual sequence of flowering plant reproduction?"},"options":[{"id":"0","text":"Pollination"},{"id":"1","text":"Germination"},{"id":"2","text":"Seed dispersal"},{"id":"3","text":"Fertilisation"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-foundation-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"What is pollination?"},"options":[{"id":"0","text":"Transfer of pollen from anther to stigma"},{"id":"1","text":"A seed growing into a plant"},{"id":"2","text":"A sperm joining an egg"},{"id":"3","text":"A fruit falling"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-foundation-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"What is the result of fertilisation in flowering plants?"},"options":[{"id":"0","text":"Development of fruits and seeds"},{"id":"1","text":"Formation of lungs"},{"id":"2","text":"Production of spores only"},{"id":"3","text":"Water evaporation"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-foundation-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"Which sequence is correct?"},"options":[{"id":"0","text":"Pollination → fertilisation → seed dispersal → germination"},{"id":"1","text":"Germination → seed dispersal → pollination → fertilisation"},{"id":"2","text":"Seed dispersal → pollination → germination → fertilisation"},{"id":"3","text":"Fertilisation → pollination → germination → seed dispersal"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-foundation-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Human fertilisation happens when…"},"options":[{"id":"0","text":"a sperm fuses with an egg"},{"id":"1","text":"a pollen grain joins a seed"},{"id":"2","text":"an ovary fuses with a fruit"},{"id":"3","text":"a spore joins an egg"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-foundation-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which comparison is correct?"},"options":[{"id":"0","text":"Some plants reproduce by spores and some by seeds"},{"id":"1","text":"All plants reproduce only by seeds"},{"id":"2","text":"Spores are the same as fertilised eggs"},{"id":"3","text":"Seeds are made by pollination alone"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-REPRO-foundation-Q6"}]},{"code":"P5-WATER-STANDARD","track":"STANDARD","topic":"Cycles in Matter and Water (Water)","strand":"Cycles","source":"MOE 2023 syllabus, pp. 49–51","outcome_text":"Recognise that water exists in three interchangeable states and explain melting, freezing, boiling/evaporation and condensation.\nUnderstand melting point of ice/freezing point of water and boiling point of water.\nExplain the roles of evaporation and condensation in the water cycle and recognise its importance.\nInvestigate the effect of heat gain or loss on water temperature and state, and factors affecting evaporation rate: wind, temperature and exposed surface area.\nRecognise the importance of water to life processes and describe impacts of water pollution on Earth's water resources.","objectives":["Describe the three states of water and changes between them.","Explain the water cycle using evaporation and condensation.","Interpret simple investigations about evaporation.","Explain why clean water is important and how pollution affects water resources."],"teaching_content":{"sections":[{"heading":"Three states of water","content":"Water can exist as solid ice, liquid water and water vapour (a gas). These states can change into one another when heat is gained or lost."},{"heading":"Changes of state","content":"Melting changes ice to liquid water at 0°C. Freezing changes water to ice at 0°C. Water boils at 100°C under normal atmospheric pressure. Evaporation can occur at temperatures below boiling. Condensation changes water vapour into liquid water."},{"heading":"The water cycle","content":"Water evaporates from surfaces. Water vapour cools and condenses into tiny droplets that form clouds. Water returns to Earth as precipitation and collects in water bodies. Evaporation and condensation are key processes."},{"heading":"Investigating evaporation","content":"Wind, higher temperature and a larger exposed surface area increase the rate of evaporation. In a fair test, change one factor and keep the others the same."},{"heading":"Water and life","content":"Water is needed for life processes. Pollution can make water unsafe and reduce the amount of usable water. Conserving water helps protect this limited natural resource."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Describe the three states of water and changes between them.","Explain the water cycle using evaporation and condensation.","Interpret simple investigations about evaporation.","Explain why clean water is important and how pollution affects water resources."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which state of water has a fixed volume but no fixed shape?"},"options":[{"id":"0","text":"Liquid"},{"id":"1","text":"Solid"},{"id":"2","text":"Gas"},{"id":"3","text":"All three"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-standard-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"What is the change from liquid water to water vapour called?"},"options":[{"id":"0","text":"Evaporation"},{"id":"1","text":"Condensation"},{"id":"2","text":"Freezing"},{"id":"3","text":"Melting"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-standard-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"Which factor can increase the rate of evaporation?"},"options":[{"id":"0","text":"Greater exposed surface area"},{"id":"1","text":"Lower temperature"},{"id":"2","text":"Still air"},{"id":"3","text":"Smaller exposed surface area"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-standard-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"A student compares evaporation in two identical dishes, one placed in moving air and one in still air. What is changed?"},"options":[{"id":"0","text":"Wind"},{"id":"1","text":"Water volume"},{"id":"2","text":"Dish material"},{"id":"3","text":"Room temperature"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-standard-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Why do water droplets form on the outside of a cold glass?"},"options":[{"id":"0","text":"Water vapour in the air condenses on the cold surface"},{"id":"1","text":"Liquid water passes through the glass"},{"id":"2","text":"The glass produces water"},{"id":"3","text":"Ice melts through the glass"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-standard-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"How can water pollution affect people and the environment?"},"options":[{"id":"0","text":"It reduces the amount of clean usable water"},{"id":"1","text":"It creates more drinking water"},{"id":"2","text":"It stops evaporation everywhere"},{"id":"3","text":"It changes all water into ice"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-standard-Q6"}]},{"code":"P5-WATER-FOUNDATION","track":"FOUNDATION","topic":"Cycles in Matter and Water (Water)","strand":"Cycles","source":"MOE 2023 syllabus, pp. 49–51","outcome_text":"Recognise that water exists in three interchangeable states and state how water changes state.\nState the melting point of ice/freezing point of water and boiling point of water.\nRecognise changes of state in the water cycle and its importance.\nCompare water in three states and show concern for conserving water as a limited natural resource.","objectives":["Identify solid, liquid and gas forms of water.","State the four changes of state and key temperatures.","Recognise evaporation and condensation in the water cycle.","Explain why water should be conserved."],"teaching_content":{"sections":[{"heading":"Three states","content":"Water exists as solid ice, liquid water and water vapour (gas)."},{"heading":"Changes of state","content":"Melting: ice to water. Freezing: water to ice. Boiling: water to steam at 100°C. Condensation: water vapour to liquid water. Ice melts and water freezes at 0°C."},{"heading":"Water cycle","content":"Water evaporates, water vapour condenses to form clouds, and water returns to Earth. The cycle is important because it moves water through the environment."},{"heading":"Conserving water","content":"Water is a limited natural resource. We can reduce waste by turning off taps and using water carefully."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Identify solid, liquid and gas forms of water.","State the four changes of state and key temperatures.","Recognise evaporation and condensation in the water cycle.","Explain why water should be conserved."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which is water in its solid state?"},"options":[{"id":"0","text":"Ice"},{"id":"1","text":"Steam"},{"id":"2","text":"Rain"},{"id":"3","text":"Water vapour"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-foundation-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"What happens when water freezes?"},"options":[{"id":"0","text":"Liquid water changes to ice"},{"id":"1","text":"Ice changes to liquid water"},{"id":"2","text":"Water vapour changes to liquid"},{"id":"3","text":"Water disappears"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-foundation-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"At what temperature does ice melt under normal conditions?"},"options":[{"id":"0","text":"0°C"},{"id":"1","text":"50°C"},{"id":"2","text":"100°C"},{"id":"3","text":"10°C"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-foundation-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"Which process changes water vapour into liquid droplets?"},"options":[{"id":"0","text":"Condensation"},{"id":"1","text":"Evaporation"},{"id":"2","text":"Melting"},{"id":"3","text":"Freezing"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-foundation-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which sequence shows water-cycle processes correctly?"},"options":[{"id":"0","text":"Evaporation then condensation"},{"id":"1","text":"Freezing then melting only"},{"id":"2","text":"Condensation then burning"},{"id":"3","text":"Melting then rusting"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-foundation-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Why should we conserve water?"},"options":[{"id":"0","text":"Usable fresh water is a limited resource"},{"id":"1","text":"Water can never be polluted"},{"id":"2","text":"All water is safe to drink"},{"id":"3","text":"Water is not needed by living things"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-WATER-foundation-Q6"}]},{"code":"P5-HUMAN-STANDARD","track":"STANDARD","topic":"Human System (Respiratory and Circulatory Systems)","strand":"Systems","source":"MOE 2023 syllabus, pp. 54–55","outcome_text":"Recognise that air contains gases including nitrogen, carbon dioxide, oxygen and water vapour.\nIdentify the nose, windpipe and lungs and the heart, blood and blood vessels, and describe their functions.\nRecognise how digestive, respiratory and circulatory systems work together in life processes.\nCompare how plants, fish and humans take in oxygen and give out carbon dioxide.\nCompare transport in plants and humans: plant tubes transport food and water; human blood vessels transport digested food, oxygen and carbon dioxide.","objectives":["Identify major parts and functions of respiratory and circulatory systems.","Explain how oxygen enters the body and is transported.","Explain how body systems work together.","Compare gas exchange and transport in plants, fish and humans at syllabus level."],"teaching_content":{"sections":[{"heading":"Air and breathing","content":"Air is a mixture of gases. It contains mainly nitrogen and oxygen, with smaller amounts of carbon dioxide and water vapour. The nose, windpipe and lungs are parts of the respiratory system."},{"heading":"Respiratory system","content":"Air enters through the nose, travels down the windpipe and reaches the lungs. Oxygen from inhaled air enters the body; carbon dioxide is removed when we breathe out."},{"heading":"Circulatory system","content":"The heart pumps blood around the body. Blood vessels carry blood. Blood transports oxygen and digested food to body parts and carries carbon dioxide away."},{"heading":"Systems work together","content":"The digestive system provides digested food, the respiratory system supplies oxygen, and the circulatory system transports these substances to cells. These systems work together to support life."},{"heading":"Comparing living things","content":"Plants, fish and humans take in oxygen and give out carbon dioxide in different ways. In plants, tubes transport water and food. In humans, blood vessels transport digested food, oxygen and carbon dioxide."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Identify major parts and functions of respiratory and circulatory systems.","Explain how oxygen enters the body and is transported.","Explain how body systems work together.","Compare gas exchange and transport in plants, fish and humans at syllabus level."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which gas in air is needed for respiration?"},"options":[{"id":"0","text":"Oxygen"},{"id":"1","text":"Nitrogen"},{"id":"2","text":"Carbon dioxide"},{"id":"3","text":"Water vapour"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-standard-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which part carries air from the nose towards the lungs?"},"options":[{"id":"0","text":"Windpipe"},{"id":"1","text":"Heart"},{"id":"2","text":"Blood vessel"},{"id":"3","text":"Stomach"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-standard-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"What is the main function of the heart?"},"options":[{"id":"0","text":"To pump blood around the body"},{"id":"1","text":"To digest food"},{"id":"2","text":"To take in air"},{"id":"3","text":"To make oxygen"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-standard-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"Which statement best explains how the systems work together?"},"options":[{"id":"0","text":"The respiratory system supplies oxygen and the circulatory system transports it to cells"},{"id":"1","text":"The heart makes digested food"},{"id":"2","text":"The lungs pump blood"},{"id":"3","text":"The digestive system supplies oxygen directly to the lungs"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-standard-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which substances are transported by human blood vessels?"},"options":[{"id":"0","text":"Digested food, oxygen and carbon dioxide"},{"id":"1","text":"Pollen and seeds"},{"id":"2","text":"Only water vapour"},{"id":"3","text":"Only nitrogen"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-standard-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which comparison is correct at P5 level?"},"options":[{"id":"0","text":"Plant tubes transport food and water; human blood vessels transport substances in blood"},{"id":"1","text":"Plants have a heart that pumps blood"},{"id":"2","text":"Fish breathe using human lungs"},{"id":"3","text":"Humans transport food through xylem"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-standard-Q6"}]},{"code":"P5-HUMAN-FOUNDATION","track":"FOUNDATION","topic":"Human System (Respiratory and Circulatory Systems)","strand":"Systems","source":"MOE 2023 syllabus, pp. 54–55","outcome_text":"Recognise that air contains nitrogen, carbon dioxide, oxygen and water vapour.\nIdentify the nose, windpipe, lungs, heart, blood and blood vessels and state their functions.\nCompare how plants and humans take in oxygen and give out carbon dioxide.\nShow objectivity by seeking information to validate explanations about the human body.","objectives":["Name the main parts of the respiratory and circulatory systems.","State the functions of these parts.","Describe how plants and humans exchange gases.","Use accurate information when explaining the human body."],"teaching_content":{"sections":[{"heading":"Air","content":"Air is a mixture of gases. It contains nitrogen, oxygen, carbon dioxide and water vapour."},{"heading":"Breathing system","content":"The nose, windpipe and lungs are parts of the respiratory system. They help air enter and leave the body."},{"heading":"Blood circulation","content":"The heart pumps blood. Blood travels through blood vessels around the body. Blood carries substances to and from body parts."},{"heading":"Plants and humans","content":"Both plants and humans take in oxygen and give out carbon dioxide. They do this using different structures."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Name the main parts of the respiratory and circulatory systems.","State the functions of these parts.","Describe how plants and humans exchange gases.","Use accurate information when explaining the human body."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which gas do humans need for respiration?"},"options":[{"id":"0","text":"Oxygen"},{"id":"1","text":"Nitrogen"},{"id":"2","text":"Carbon dioxide"},{"id":"3","text":"Water vapour"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-foundation-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which organ pumps blood?"},"options":[{"id":"0","text":"Heart"},{"id":"1","text":"Lungs"},{"id":"2","text":"Nose"},{"id":"3","text":"Windpipe"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-foundation-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"Which are parts of the respiratory system?"},"options":[{"id":"0","text":"Nose, windpipe and lungs"},{"id":"1","text":"Heart, blood and blood vessels"},{"id":"2","text":"Stomach and intestine"},{"id":"3","text":"Roots and leaves"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-foundation-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"What is the function of blood vessels?"},"options":[{"id":"0","text":"They carry blood around the body"},{"id":"1","text":"They digest food"},{"id":"2","text":"They take in air"},{"id":"3","text":"They produce eggs"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-foundation-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which statement is correct?"},"options":[{"id":"0","text":"Plants and humans take in oxygen and give out carbon dioxide"},{"id":"1","text":"Plants breathe using a human heart"},{"id":"2","text":"Humans take in carbon dioxide for respiration"},{"id":"3","text":"Blood vessels carry air into the lungs"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-foundation-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Why should we check information before explaining the human body?"},"options":[{"id":"0","text":"To make sure our explanation is supported by accurate evidence"},{"id":"1","text":"To make our explanation longer"},{"id":"2","text":"To avoid observing anything"},{"id":"3","text":"To replace evidence with guesses"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-HUMAN-foundation-Q6"}]},{"code":"P5-PLANT-STANDARD","track":"STANDARD","topic":"Plant System (Respiratory and Circulatory Systems)","strand":"Systems","source":"MOE 2023 syllabus, pp. 57–58","outcome_text":"Identify parts of the plant transport system and describe their functions.\nInvestigate how food and water are transported in plants.\nRecognise that specific terms xylem and phloem, relative positions of tubes and transpiration pull are not required.","objectives":["Explain that plants transport water from roots to other parts.","Explain that plants transport food from leaves to other parts.","Interpret a simple investigation showing transport in plants."],"teaching_content":{"sections":[{"heading":"Plants are systems","content":"A plant has parts that work together. Roots absorb water. Leaves make food. The plant transport system moves water and food to where they are needed."},{"heading":"Transporting water","content":"Water absorbed by the roots is transported through water-carrying tubes to other parts of the plant, including the leaves."},{"heading":"Transporting food","content":"Food made in the leaves is transported through food-carrying tubes to other parts of the plant for growth and other life processes."},{"heading":"Investigating transport","content":"A coloured-water investigation can show water movement through a plant stem. Keep the plant, water amount and time consistent when comparing results."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Explain that plants transport water from roots to other parts.","Explain that plants transport food from leaves to other parts.","Interpret a simple investigation showing transport in plants."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Where does a plant mainly absorb water from?"},"options":[{"id":"0","text":"Roots"},{"id":"1","text":"Flowers"},{"id":"2","text":"Fruits"},{"id":"3","text":"Seeds"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-standard-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Where is food made in a green plant?"},"options":[{"id":"0","text":"Leaves"},{"id":"1","text":"Roots"},{"id":"2","text":"Flowers only"},{"id":"3","text":"Soil"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-standard-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"What is the function of the plant transport system?"},"options":[{"id":"0","text":"To move water and food to different parts"},{"id":"1","text":"To make the plant move from place to place"},{"id":"2","text":"To produce sunlight"},{"id":"3","text":"To absorb oxygen only"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-standard-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"A cut stem is placed in coloured water. The colour later appears in the leaf veins. What does this show?"},"options":[{"id":"0","text":"Water is transported through the plant"},{"id":"1","text":"Food is made in the roots"},{"id":"2","text":"The leaves absorb soil"},{"id":"3","text":"The stem produces water"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-standard-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which statement is correct?"},"options":[{"id":"0","text":"Water moves from roots to other parts; food moves from leaves to other parts"},{"id":"1","text":"Water is made in flowers and moves to roots"},{"id":"2","text":"Food is made in soil and enters leaves"},{"id":"3","text":"Plants do not transport substances"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-standard-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Why should the same time period be used when comparing two plant transport tests?"},"options":[{"id":"0","text":"To make the comparison fair"},{"id":"1","text":"To change two variables at once"},{"id":"2","text":"To prevent any observation"},{"id":"3","text":"To make the plant stop growing"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-standard-Q6"}]},{"code":"P5-PLANT-FOUNDATION","track":"FOUNDATION","topic":"Plant System (Respiratory and Circulatory Systems)","strand":"Systems","source":"MOE 2023 syllabus, pp. 57–58","outcome_text":"Recognise how water is transported from roots to other parts of a plant and how food is transported from leaves to other parts.\nObserve how food and water are transported in plants.\nShow objectivity and care when investigating plant parts and functions.","objectives":["State where water enters a plant and where it is transported.","State where food is made and where it is transported.","Observe evidence of transport in plants."],"teaching_content":{"sections":[{"heading":"Water transport","content":"Roots absorb water from the soil. Water is transported from the roots to other parts of the plant."},{"heading":"Food transport","content":"Leaves make food. Food is transported from the leaves to other parts of the plant."},{"heading":"Observe transport","content":"A plant stem placed in coloured water may show colour moving upwards. This is evidence that water is transported through the plant."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":[]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["State where water enters a plant and where it is transported.","State where food is made and where it is transported.","Observe evidence of transport in plants."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which plant part absorbs water from the soil?"},"options":[{"id":"0","text":"Roots"},{"id":"1","text":"Leaves"},{"id":"2","text":"Flowers"},{"id":"3","text":"Fruit"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-foundation-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which plant part makes food?"},"options":[{"id":"0","text":"Leaves"},{"id":"1","text":"Roots"},{"id":"2","text":"Stem only"},{"id":"3","text":"Seeds"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-foundation-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"Where is water transported from?"},"options":[{"id":"0","text":"Roots"},{"id":"1","text":"Flowers"},{"id":"2","text":"Fruits"},{"id":"3","text":"Leaves only"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-foundation-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"Where is food transported from?"},"options":[{"id":"0","text":"Leaves"},{"id":"1","text":"Soil"},{"id":"2","text":"Roots only"},{"id":"3","text":"Water"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-foundation-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"A white flower changes colour after its stem is placed in coloured water. What does this show?"},"options":[{"id":"0","text":"Water moves through the stem to other parts"},{"id":"1","text":"The flower makes coloured food"},{"id":"2","text":"The roots absorb colour from air"},{"id":"3","text":"The plant has stopped transporting water"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-foundation-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which statement describes plant transport correctly?"},"options":[{"id":"0","text":"Water moves from roots; food moves from leaves"},{"id":"1","text":"Water and food are made in the soil"},{"id":"2","text":"Food moves only into roots"},{"id":"3","text":"Plants do not need transport"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-PLANT-foundation-Q6"}]},{"code":"P5-ELECTRIC-STANDARD","track":"STANDARD","topic":"Electrical System","strand":"Systems","source":"MOE 2023 syllabus, pp. 59–60","outcome_text":"Recognise an electrical system as a circuit with an energy source (battery) and components such as wire, bulb and switch.\nExplain that a closed circuit allows current to flow.\nIdentify electrical conductors and insulators.\nConstruct simple circuits from circuit diagrams.\nInvestigate effects on current of the number of batteries in series and the number of bulbs in series and parallel.\nShow concern for conserving electricity and handling it properly.","objectives":["Identify components of a simple electrical circuit.","Explain the difference between open and closed circuits.","Classify conductors and insulators.","Predict effects of changing batteries and bulbs in series and parallel."],"teaching_content":{"sections":[{"heading":"An electrical system","content":"A simple electrical system can include a battery, connecting wires, a bulb and a switch. The battery is the energy source."},{"heading":"Open and closed circuits","content":"A closed circuit is a complete path that allows current to flow and the bulb to light. An open circuit has a break, so current cannot flow."},{"heading":"Conductors and insulators","content":"Conductors allow electricity to pass through them; insulators do not allow electricity to pass through easily. Metals are commonly used as conductors; plastic is commonly used as an insulator."},{"heading":"Changing a circuit","content":"Adding batteries in series increases the energy supplied. Adding bulbs in series generally makes each bulb dimmer. In a parallel arrangement, bulbs have separate branches."},{"heading":"Electrical safety","content":"Use only low-voltage batteries in classroom investigations. Never experiment with mains electricity. Switch off devices when not in use."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":["Use low-voltage batteries only. Never use mains electricity."]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Identify components of a simple electrical circuit.","Explain the difference between open and closed circuits.","Classify conductors and insulators.","Predict effects of changing batteries and bulbs in series and parallel."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which component is the energy source in a simple circuit?"},"options":[{"id":"0","text":"Battery"},{"id":"1","text":"Bulb"},{"id":"2","text":"Switch"},{"id":"3","text":"Wire"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-standard-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"What must a circuit have for current to flow?"},"options":[{"id":"0","text":"A complete closed path"},{"id":"1","text":"A broken wire"},{"id":"2","text":"An open switch"},{"id":"3","text":"No battery"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-standard-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"Which material is usually an electrical insulator?"},"options":[{"id":"0","text":"Plastic"},{"id":"1","text":"Copper"},{"id":"2","text":"Iron"},{"id":"3","text":"Aluminium"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-standard-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"What happens when a switch opens a simple series circuit?"},"options":[{"id":"0","text":"The path is broken and the bulb goes off"},{"id":"1","text":"The bulb becomes brighter"},{"id":"2","text":"The battery becomes a bulb"},{"id":"3","text":"Current increases"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-standard-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"What is the expected effect of adding another identical bulb in series to a battery circuit?"},"options":[{"id":"0","text":"The bulbs become dimmer"},{"id":"1","text":"The bulbs become brighter"},{"id":"2","text":"The circuit becomes parallel"},{"id":"3","text":"The battery stops being an energy source"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-standard-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which investigation is a fair test of the effect of battery number?"},"options":[{"id":"0","text":"Change the number of batteries and keep other components the same"},{"id":"1","text":"Change batteries, bulbs and wires together"},{"id":"2","text":"Use different bulbs each time"},{"id":"3","text":"Change the battery and the wire material together"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-standard-Q6"}]},{"code":"P5-ELECTRIC-FOUNDATION","track":"FOUNDATION","topic":"Electrical System","strand":"Systems","source":"MOE 2023 syllabus, pp. 59–60","outcome_text":"Recognise a simple electrical system consisting of a battery, wire, bulb and switch.\nState that a closed circuit allows current to flow.\nIdentify electrical conductors and insulators.\nConstruct simple circuits from diagrams.\nInvestigate effects of batteries in series and bulbs in series.\nShow concern for conserving and handling electricity properly.","objectives":["Name the parts of a simple circuit.","State what happens in a closed circuit.","Identify conductors and insulators.","Construct simple series circuits and describe safe use of electricity."],"teaching_content":{"sections":[{"heading":"Circuit parts","content":"A simple circuit has a battery, wires, a bulb and sometimes a switch. The battery provides energy."},{"heading":"Closed circuits","content":"A closed circuit is a complete path. Current can flow and the bulb lights. If the path is broken, the bulb goes off."},{"heading":"Conductors and insulators","content":"Conductors allow electricity to pass through. Insulators do not allow electricity to pass through easily."},{"heading":"Series circuits","content":"Batteries and bulbs can be connected in series. Adding batteries can make a bulb brighter. Adding bulbs in series generally makes bulbs dimmer. Use safe low-voltage batteries only."}],"teaching_language":"English","pedagogy":["Explain","Model","Check understanding","Connect to daily life"],"safety_notes":["Use low-voltage batteries only. Never use mains electricity."]},"practice_blueprint":{"selection":"difficulty 1–3","question_count":3,"feedback":"Immediate feedback after submission"},"test_blueprint":{"selection":"difficulty 4–5","question_count":3,"independent":true},"summary_blueprint":{"key_takeaways":["Name the parts of a simple circuit.","State what happens in a closed circuit.","Identify conductors and insulators.","Construct simple series circuits and describe safe use of electricity."],"reflection_prompts":["What idea can you explain confidently?","Which part would you like to practise again?"]},"questions":[{"question_type":"MCQ","difficulty":1,"prompt":{"question":"Which item provides energy in a simple circuit?"},"options":[{"id":"0","text":"Battery"},{"id":"1","text":"Bulb"},{"id":"2","text":"Wire"},{"id":"3","text":"Switch"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-foundation-Q1"},{"question_type":"MCQ","difficulty":1,"prompt":{"question":"What happens in a closed circuit?"},"options":[{"id":"0","text":"Current can flow"},{"id":"1","text":"The wire disappears"},{"id":"2","text":"The battery becomes an insulator"},{"id":"3","text":"The switch must be open"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-foundation-Q2"},{"question_type":"MCQ","difficulty":2,"prompt":{"question":"Which material is an insulator?"},"options":[{"id":"0","text":"Plastic"},{"id":"1","text":"Copper"},{"id":"2","text":"Iron"},{"id":"3","text":"Aluminium"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-foundation-Q3"},{"question_type":"MCQ","difficulty":4,"prompt":{"question":"What happens if a wire is disconnected in a simple circuit?"},"options":[{"id":"0","text":"The circuit is open and the bulb goes off"},{"id":"1","text":"The bulb becomes brighter"},{"id":"2","text":"The circuit becomes closed"},{"id":"3","text":"The battery creates another path"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-foundation-Q4"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"What is likely to happen when more identical bulbs are added in series?"},"options":[{"id":"0","text":"The bulbs become dimmer"},{"id":"1","text":"The bulbs become brighter"},{"id":"2","text":"The bulbs become batteries"},{"id":"3","text":"The circuit has no wires"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-foundation-Q5"},{"question_type":"MCQ","difficulty":5,"prompt":{"question":"Which is the safest way to investigate circuits at school?"},"options":[{"id":"0","text":"Use low-voltage batteries and never use mains electricity"},{"id":"1","text":"Use a wall socket"},{"id":"2","text":"Touch bare wires connected to mains"},{"id":"3","text":"Pour water on the circuit"}],"answer_key":{"correct_option":"0"},"marks":1,"source_reference":"ZEE-SCI-P5-ELECTRIC-foundation-Q6"}]}]$seed$::jsonb)
  loop
    insert into public.science_learning_outcomes
      (syllabus_version_id,outcome_code,level,track,strand,topic,outcome_text,science_practices,values_attitudes,source_page,verification_status)
    values
      (v_syllabus,r->>'code','P5',r->>'track',r->>'strand',r->>'topic',r->>'outcome_text',
       case when r->>'track'='STANDARD' and r->>'topic' like '%Water%' then array['Compare water in three states','Investigate effects of heat gain and loss','Investigate factors affecting evaporation']
            when r->>'topic' like '%Electrical%' then array['Construct simple circuits','Investigate variables in circuits']
            when r->>'topic' like '%Plant System%' then array['Investigate transport of food and water in plants']
            when r->>'topic' like '%Human System%' then array['Compare gas exchange','Compare transport of substances']
            when r->>'topic' like '%Reproduction%' then array['Investigate reproduction by spores and seeds']
            else array[]::text[] end,
       case when r->>'topic' like '%Reproduction%' then array['Curiosity','Care and concern for living things']
            when r->>'topic' like '%Water%' then array['Concern for water as a limited natural resource']
            when r->>'topic' like '%Human System%' then array['Objectivity']
            when r->>'topic' like '%Plant System%' then array['Objectivity','Care and concern for plants']
            when r->>'topic' like '%Electrical%' then array['Conservation and safe handling of electricity']
            else array[]::text[] end,
       r->>'source','verified')
    on conflict (syllabus_version_id,outcome_code,track) do update
      set outcome_text=excluded.outcome_text,science_practices=excluded.science_practices,
          values_attitudes=excluded.values_attitudes,source_page=excluded.source_page,
          verification_status='verified'
    returning id into v_outcome;

    select id into v_outcome from public.science_learning_outcomes
    where syllabus_version_id=v_syllabus and outcome_code=r->>'code' and track=r->>'track';

    insert into public.science_lessons
      (syllabus_version_id,level,track,title,topic,lesson_order,learning_objectives,
       teaching_content,practice_blueprint,test_blueprint,summary_blueprint,outcome_ids,status)
    select v_syllabus,'P5',r->>'track',r->>'topic',r->>'topic',
      case r->>'topic'
        when 'Cycles in Plants and Animals (Reproduction)' then 1
        when 'Cycles in Matter and Water (Water)' then 2
        when 'Human System (Respiratory and Circulatory Systems)' then 3
        when 'Plant System (Respiratory and Circulatory Systems)' then 4
        when 'Electrical System' then 5 else 99 end,
      r->'objectives',r->'teaching_content',r->'practice_blueprint',r->'test_blueprint',
      r->'summary_blueprint',array[v_outcome],'published'
    where not exists (
      select 1 from public.science_lessons l
      where l.syllabus_version_id=v_syllabus and l.level='P5'
        and l.track=r->>'track' and l.topic=r->>'topic'
    )
    returning id into v_lesson;

    if v_lesson is null then
      select id into v_lesson from public.science_lessons
      where syllabus_version_id=v_syllabus and level='P5'
        and track=r->>'track' and topic=r->>'topic'
      order by created_at limit 1;
      update public.science_lessons set
        learning_objectives=r->'objectives',teaching_content=r->'teaching_content',
        practice_blueprint=r->'practice_blueprint',test_blueprint=r->'test_blueprint',
        summary_blueprint=r->'summary_blueprint',outcome_ids=array[v_outcome],
        status='published',updated_at=now()
      where id=v_lesson and status <> 'retired';
    end if;

    for q in select value from jsonb_array_elements(r->'questions')
    loop
      insert into public.science_question_bank
        (syllabus_version_id,lesson_id,outcome_id,level,track,question_type,difficulty,
         prompt,options,answer_key,rubric,marks,source_reference,status)
      select v_syllabus,v_lesson,v_outcome,'P5',r->>'track',q->>'question_type',
        (q->>'difficulty')::smallint,q->'prompt',q->'options',q->'answer_key',
        '{}'::jsonb,coalesce((q->>'marks')::numeric,1),q->>'source_reference','published'
      where not exists (
        select 1 from public.science_question_bank qb
        where qb.source_reference=q->>'source_reference'
      );
    end loop;
  end loop;

  update public.science_syllabus_versions
  set status='published'
  where id=v_syllabus and status in ('draft','reviewed');
end $$;
